"""Local result raster catalog and XYZ viewer; contains no credentials."""

HTML = r'''<!doctype html>
<html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><meta name="referrer" content="no-referrer"><title>AeroNexusAdvanced · Ergebnisraster</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="">
<style>
:root{font:14px/1.45 system-ui,"Segoe UI",sans-serif;color-scheme:dark;--bg:#0b1323;--pane:#122139;--line:#334e69;--ink:#eaf4ff;--sub:#a9bfd8;--mint:#75e3bd;--red:#ff9ba8}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink)}a{color:#9dd5ff}button,select,input{font:inherit;color:var(--ink);background:#213d5e;border:1px solid #426487;border-radius:8px;padding:8px;min-width:0}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}:focus-visible{outline:2px solid var(--mint);outline-offset:2px}header{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:12px 20px;background:#142440;border-bottom:1px solid var(--line)}.logo{font-size:18px;font-weight:800}.logo small{display:block;font-size:10px;letter-spacing:.18em;color:#7abef0}nav{display:flex;flex-wrap:wrap;gap:13px;font-size:13px}nav a{text-decoration:none}nav span{color:var(--mint);font-weight:700}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:12px;padding:12px;min-height:calc(100vh - 76px)}.panel{background:var(--pane);border:1px solid var(--line);border-radius:13px;padding:14px;min-width:0}h1,h2{font-size:17px;margin:0 0 10px}.sub{font-size:12px;color:var(--sub)}.row{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.search{display:flex;gap:5px;margin:12px 0}.search input{flex:1;width:100%}.item{display:block;width:100%;text-align:left;margin:7px 0;padding:11px;background:#142842;overflow-wrap:anywhere}.item[aria-pressed=true]{border-color:var(--mint);background:#214362}.item b,.item small{display:block}.item small{color:var(--sub);margin-top:4px}.list{max-height:52vh;overflow:auto}.pager{justify-content:space-between;margin:12px 0}.toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:12px 0}.toolbar label{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--sub)}.toolbar input[type=number]{width:105px}fieldset{border:0;padding:0;margin:0;min-width:0}#map{height:55vh;min-height:340px;background:#23374f;border:1px solid var(--line);border-radius:9px}.meta{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:4px 12px;font-size:12px}.meta dt{color:var(--sub)}.meta dd{margin:0;overflow-wrap:anywhere}.error{color:var(--red)}.note{color:#e4bd78;font-size:12px;white-space:pre-line}.legend{display:flex;align-items:center;gap:8px;font-size:12px;margin:9px 0}.legend i{display:block;width:160px;height:12px;border-radius:3px}#state,#map-state{min-height:1.5em}#scan-report{overflow-wrap:anywhere}button:hover:enabled{border-color:#9dd5ff}@media(max-width:800px){.layout{display:flex;flex-direction:column}.list{max-height:260px}#map{height:50vh;min-height:300px}.toolbar input[type=number]{width:90px}}
</style></head><body>
<header><div class="logo"><small>AERONEXUS ADVANCED</small>Ergebnisraster</div><nav aria-label="Projektbereiche"><a href="/operations">Operations Center</a><a href="/studio">Mission Studio</a><a href="/status">Live-Status</a><a href="/media">DJI Medien</a><a href="/thermal">Thermal</a><a href="/multispectral">Multispektral</a><span aria-current="page">Ergebnisraster</span></nav></header>
<main class="layout"><section class="panel" aria-labelledby="catalog-title"><h1 id="catalog-title">GeoTIFF / COG</h1><p class="sub">Fertige Ergebnisdateien im konfigurierten lokalen Ergebnisordner. Originale bleiben unverändert.</p><div class="row"><button id="scan" type="button">Ordner einlesen</button><button id="refresh" type="button">Aktualisieren</button></div><p id="scan-report" class="note" role="status"></p><label class="sub" for="query">Dateiname suchen</label><div class="search"><input id="query" type="search" maxlength="120" autocomplete="off"><button id="clear" type="button" aria-label="Suche zurücksetzen">×</button></div><div id="state" class="sub" role="status" aria-live="polite">Lade Katalog…</div><div id="list" class="list" aria-label="Ergebnisdateien"></div><div class="row pager"><button id="prev" type="button">Zurück</button><span id="count" class="sub"></span><button id="next" type="button">Weiter</button></div><p id="scanned" class="sub"></p><a href="/docs" class="sub">API-Dokumentation</a></section>
<section class="panel" aria-labelledby="title"><h2 id="title">Ergebnis auswählen</h2><div id="warnings" class="note"></div><fieldset id="controls" disabled><legend class="sub">Darstellung · keine Änderung der Messwerte</legend><div class="toolbar"><label>Band / Modus<select id="band"></select></label><label>Farben<select id="palette"><option value="viridis">Viridis</option><option value="rdylgn">Rot–Gelb–Grün</option><option value="gray">Graustufen</option><option value="terrain">Gelände</option></select></label><label>Untergrenze<input id="low" type="number" step="any" value="0"></label><label>Obergrenze<input id="high" type="number" step="any" value="1"></label><button id="apply" type="button">Anwenden</button><button id="auto" type="button">Kontrast P2–P98</button><button id="fit" type="button">Auf Raster zoomen</button><label>Deckkraft<input id="opacity" type="range" min="0" max="1" step="0.05" value="1"></label></div></fieldset><p id="map-state" class="sub" role="status" aria-live="polite">Kartenkacheln werden erst nach Auswahl geladen.</p><button id="retry" type="button" hidden>Kacheln erneut laden</button><div id="map" role="region" aria-label="Karte der Ergebnisraster"></div><div id="legend" class="legend" hidden><span id="legend-low"></span><i id="gradient"></i><span id="legend-high"></span><span id="legend-unit"></span></div><p class="sub">Transparente Bereiche: NoData oder außerhalb des Rasters. Ohne Hintergrundkarte. Die Farbdarstellung ist keine radiometrische Kalibrierung.</p><dl id="meta" class="meta"></dl></section></main>
<script src="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script><script>
'use strict';
const $=id=>document.getElementById(id);
let items=[],selected=null,map=null,layer=null,offset=0,total=0,listSeq=0,selectSeq=0,tileSeq=0,statsController=null,listController=null,searchTimer=null;
const gradients={viridis:'linear-gradient(90deg,#440154,#3b528b,#21918c,#5ec962,#fde725)',rdylgn:'linear-gradient(90deg,#a50026,#f46d43,#ffffbf,#66bd63,#006837)',gray:'linear-gradient(90deg,#000,#fff)',terrain:'linear-gradient(90deg,#1e5a41,#7da05a,#cdbe91,#9b7d64,#f5f5f5)'};
function status(id,message,error=false){$(id).textContent=message;$(id).classList.toggle('error',error);}
async function api(url,options={}){const response=await fetch(url,{...options,credentials:'same-origin',cache:'no-store'});let data;try{data=await response.json();}catch{throw Error('Ungültige Serverantwort.');}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Anfrage fehlgeschlagen ('+response.status+').');return data;}
function dropLayer(){tileSeq++;if(layer&&map)map.removeLayer(layer);layer=null;$('retry').hidden=true;$('legend').hidden=true;}
function resetSelection(){selectSeq++;if(statsController)statsController.abort();selected=null;dropLayer();$('controls').disabled=true;$('title').textContent='Ergebnis auswählen';$('meta').replaceChildren();$('warnings').textContent='';status('map-state','Ergebnis aus dem Katalog wählen.');}
function listButtons(){$('prev').disabled=offset===0;$('next').disabled=offset+50>=total;}
function drawList(){const fragment=document.createDocumentFragment();for(const item of items){const button=document.createElement('button');button.type='button';button.className='item';button.setAttribute('aria-pressed',String(selected?.id===item.id));const title=document.createElement('b');title.textContent=item.filename;const small=document.createElement('small');small.textContent=(item.cog?'COG':'GeoTIFF')+' · '+item.kind.toUpperCase()+' · '+item.width+' × '+item.height;button.append(title,small);button.addEventListener('click',()=>choose(item));fragment.append(button);}$('list').replaceChildren(fragment);}
async function loadList(){const seq=++listSeq;if(listController)listController.abort();listController=new AbortController();status('state','Lade Katalog…');try{const data=await api('/api/v1/results?'+new URLSearchParams({q:$('query').value,limit:50,offset}),{signal:listController.signal});if(seq!==listSeq)return;items=data.items;offset=data.offset;total=data.total;if(selected){const fresh=items.find(i=>i.id===selected.id);if(!fresh||fresh.version!==selected.version)resetSelection();}drawList();listButtons();$('count').textContent=total?`${offset+1}–${offset+items.length} / ${total}`:'0 Ergebnisse';$('scanned').textContent=data.scanned_at?'Zuletzt eingelesen: '+new Date(data.scanned_at).toLocaleString('de-DE'):'Noch kein Ordner eingelesen.';$('scan').disabled=!data.raster_available;status('state',!data.raster_available?'Raster-Unterstützung fehlt. Extra [raster] installieren.':total?'Ergebnis zum Anzeigen wählen.':$('query').value?'Keine passenden Dateinamen.':'Noch keine Raster. GeoTIFFs ablegen und Ordner einlesen.',!data.raster_available);}catch(error){if(seq!==listSeq||error.name==='AbortError')return;items=[];total=0;drawList();listButtons();$('count').textContent='';resetSelection();status('state',error.message,true);}}
function metadata(item){$('meta').replaceChildren();const rows=[['Datei',item.filename],['Format',item.cog?'COG (GDAL-Kennzeichnung)':'GeoTIFF'],['Typ',item.kind],['Koordinatensystem',item.crs],['Raster',`${item.width} × ${item.height} · ${item.bands.length} Band/Bänder`],['Größe',(item.size_bytes/1048576).toFixed(1)+' MiB'],['WGS84-Grenzen',item.bounds.map(n=>n.toFixed(6)).join(', ')]];for(const band of item.bands)rows.push(['Band '+band.index,`${band.name} · ${band.dtype} · NoData: ${band.nodata??'nicht gesetzt'} · Pyramiden: ${band.overviews.join(', ')||'keine'} · Faktor ${band.scale}, Offset ${band.offset}`]);for(const [label,value] of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;$('meta').append(dt,dd);}}
function fit(){if(map&&selected){const b=selected.bounds;map.fitBounds([[b[1],b[0]],[b[3],b[2]]],{padding:[20,20],maxZoom:20});}}
function render(){if(!selected)return;const low=Number($('low').value),high=Number($('high').value);if(!$('low').value.trim()||!$('high').value.trim()||!Number.isFinite(low)||!Number.isFinite(high)||high<=low||Math.abs(low)>1e15||Math.abs(high)>1e15){status('map-state','Endliche Grenzen eingeben: Obergrenze muss größer als Untergrenze sein.',true);return;}dropLayer();if(!map){status('map-state','Kartenbibliothek nicht verfügbar. Internetzugang für Leaflet prüfen und Seite neu laden.',true);return;}const seq=tileSeq, rgb=$('band').value==='rgb',band=rgb?1:Number($('band').value);const params=new URLSearchParams({v:selected.version,band,mode:rgb?'rgb':'scalar',palette:$('palette').value,low,high});const b=selected.bounds;let failed=0;layer=L.tileLayer('/api/v1/results/'+selected.id+'/tiles/{z}/{x}/{y}.png?'+params,{tileSize:256,minZoom:0,maxZoom:22,bounds:[[b[1],b[0]],[b[3],b[2]]],noWrap:true,opacity:Number($('opacity').value)});layer.on('loading',()=>{if(seq===tileSeq)status('map-state','Lade Kacheln…');});layer.on('tileerror',()=>{if(seq!==tileSeq)return;failed++;$('retry').hidden=false;status('map-state','Kacheln konnten nicht geladen werden. Bei geänderten Dateien den Ordner erneut einlesen.',true);});layer.on('load',()=>{if(seq===tileSeq&&!failed)status('map-state','Kacheln geladen · Web Mercator · Bandwerte mit Faktor und Offset.');});layer.addTo(map);$('legend').hidden=false;$('legend-low').textContent=String(low);$('legend-high').textContent=String(high);$('gradient').style.background=rgb?'linear-gradient(90deg,#000,#fff)':gradients[$('palette').value];$('legend-unit').textContent=rgb?'RGB-Kanalbereich':selected.bands[band-1].unit||'Bandwerte';}
async function autoRange(){if(!selected||$('band').value==='rgb')return;const seq=++selectSeq,id=selected.id,band=Number($('band').value);if(statsController)statsController.abort();statsController=new AbortController();$('auto').disabled=true;dropLayer();status('map-state','Ermittle ungefähren Kontrast aus maximal 256 × 256 Stichproben…');try{const data=await api('/api/v1/results/'+id+'/statistics?'+new URLSearchParams({band,v:selected.version}),{signal:statsController.signal});if(seq!==selectSeq)return;$('low').value=data.p02;$('high').value=data.p98;render();}catch(error){if(seq===selectSeq&&error.name!=='AbortError')status('map-state',error.message,true);}finally{if(seq===selectSeq)$('auto').disabled=false;}}
function choose(item){resetSelection();selected=item;$('title').textContent=item.filename;$('warnings').textContent=item.warnings.join('\n');metadata(item);$('band').replaceChildren();if(item.rgb_bands.length===3){const option=document.createElement('option');option.value='rgb';option.textContent='RGB (markierte Farbbänder)';$('band').append(option);}for(const b of item.bands){const option=document.createElement('option');option.value=b.index;option.textContent='Band '+b.index+' · '+b.name;$('band').append(option);}$('controls').disabled=false;$('auto').disabled=false;drawList();fit();bandChanged();}
function bandChanged(){selectSeq++;if(statsController)statsController.abort();const rgb=$('band').value==='rgb';$('auto').disabled=rgb;$('palette').disabled=rgb;$('low').value=rgb?0:['ndvi','gndvi','ndre','lci'].includes(selected.kind)?-1:0;$('high').value=rgb?255:1;if(rgb||['ndvi','gndvi','ndre','lci'].includes(selected.kind))render();else autoRange();}
$('scan').addEventListener('click',async()=>{$('scan').disabled=true;status('scan-report','Ordner wird eingelesen…');try{const report=await api('/api/v1/results/scan',{method:'POST'});status('scan-report',`${report.indexed} registriert, ${report.rejected} abgelehnt.`+(report.errors.length?'\n'+report.errors.map(e=>e.filename+': '+e.message).join('\n'):''));await loadList();}catch(error){status('scan-report',error.message,true);}finally{$('scan').disabled=false;}});
$('refresh').addEventListener('click',loadList);$('query').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{offset=0;loadList();},250);});$('clear').addEventListener('click',()=>{clearTimeout(searchTimer);$('query').value='';offset=0;loadList();$('query').focus();});$('prev').addEventListener('click',()=>{offset=Math.max(0,offset-50);loadList();});$('next').addEventListener('click',()=>{offset+=50;loadList();});$('band').addEventListener('change',bandChanged);$('apply').addEventListener('click',()=>{selectSeq++;statsController?.abort();$('auto').disabled=$('band').value==='rgb';render();});$('auto').addEventListener('click',autoRange);$('fit').addEventListener('click',fit);$('retry').addEventListener('click',render);$('opacity').addEventListener('input',()=>layer?.setOpacity(Number($('opacity').value)));
try{if(typeof L!=='undefined')map=L.map('map',{maxZoom:22}).setView([49.155,8.585],13);}catch{status('map-state','Karte nicht verfügbar. Seite neu laden.',true);}loadList();
</script></body></html>'''


def render_results_page() -> str:
    return HTML
